suppressPackageStartupMessages(library(data.table));setDTthreads(1)
P<-normalizePath('ccRCC_signature_transportability_benchmark_2026');O<-file.path(P,'84_JCO_PO_Upgrade_20261113/05_analysis/B1_operator_panel_trials');R<-file.path(O,'results');checks<-list()
old<-readRDS(file.path(P,'37_A_clinical_workflow_validation_20260917/local_only/INPUTS.rds'));parity<-list()
for(tr in names(old)){pp<-readRDS(file.path('/LOCAL_EXTERNAL_DRIVE/MacBook_Project_Storage/JCO_PO_Upgrade_scratch_20261113/B1',paste0(tr,'_prepared.rds')));gm<-fread(file.path(R,paste0(tr,'_gene_coverage.csv')));for(sig in c('Angio16','Angio36')){gg<-gm[signature==sig];err<-max(abs(unname(pp$x[gg$matrix_gene,,drop=FALSE])-unname(old[[tr]]$M[[sig]][gg$source_gene,,drop=FALSE])));parity[[length(parity)+1]]<-data.frame(trial=tr,signature=sig,genes=nrow(gg),n=ncol(pp$x),max_abs_expression_error=err);stopifnot(err<1e-8)};rm(pp);gc()};fwrite(rbindlist(parity),file.path(R,'full_matrix_historical_input_parity.csv'))
rep<-fread(file.path(R,'reproduction_full.csv'));rr<-fread(file.path(R,'pairwise_metrics.csv'));repf<-fread(file.path(R,'reproduction_frozen.csv'));ff<-fread(file.path(R,'frozen_pairwise.csv'));repc<-fread(file.path(R,'reproduction_interaction.csv'));cc<-fread(file.path(R,'interaction_HR.csv'))
for(tr in c('JAVELIN','IMmotion151')){d<-fread(file.path(R,paste0(tr,'_scores_local_only.csv')));n<-unique(d$ID);for(sig in c('Angio16','Angio36')){a<-rep[trial==tr&signature==sig];b<-rr[trial==tr&signature==sig&operator1=='O1'&operator2=='O2'];stopifnot(a$disagreement_n==b$disagreement_n);for(re in 1:5){a<-repf[trial==tr&signature==sig&partition==re];b<-ff[trial==tr&signature==sig&partition==re&operator1=='O1'&operator2=='O2'];stopifnot(a$disagreement_n==b$disagreement_n,b$n_available==a$n)};for(op in c('O1','O2')){a<-repc[trial==tr&signature==sig&operator==op];b<-cc[trial==tr&signature==sig&operator==op];stopifnot(abs(a$HR-b$interaction_HR)<1e-10)}
# Reconstruct each non-unanimous numerator directly from all saved high/low calls.
z<-d[signature==sig&available==TRUE];w<-dcast(z,ID~operator,value.var='research_high');h<-as.matrix(w[,-1]);non<-rowSums(h)>0&rowSums(h)<ncol(h);u<-fread(file.path(R,'non_unanimous.csv'))[trial==tr&signature==sig];stopifnot(sum(non)==u$non_unanimous_n)
