stopifnot(all(rr[!is.na(disagreement_pct)]$disagreement_pct>=0),all(rr[!is.na(disagreement_pct)]$disagreement_pct<=100),all(rr[operator1==operator2&n_available>0]$disagreement_n==0),all(cc[available==TRUE]$interaction_HR>0),all(cc[available==TRUE]$ci_low<=cc[available==TRUE]$interaction_HR),all(cc[available==TRUE]$ci_high>=cc[available==TRUE]$interaction_HR),all(is.na(cc[available==TRUE]$warnings)|cc[available==TRUE]$warnings==''))
